/**
 * Logotipo del encabezado: monograma IS + divisor + bloque tipográfico.
 */
export default function BrandLogo({
  className = 'inline-flex items-center gap-3 sm:gap-4 group transition-opacity hover:opacity-95',
}) {
  return (
    <div className={className}>
      <span className="sr-only">Subastas Insignia · Obras de Arte y Antigüedades</span>
      <InsigniaMonogram className="h-[44px] sm:h-[52px] w-auto text-[#e2d7c0] shrink-0" />
      <div className="h-[40px] sm:h-[46px] w-[1px] bg-white/25 shrink-0" aria-hidden="true" />
      <BrandLockup className="h-[44px] sm:h-[52px] w-auto text-white shrink-0" />
    </div>
  );
}

/**
 * Logotipo vertical para el pie de página.
 */
export function BrandLogoVertical({
  className = 'flex flex-col items-center text-center',
}) {
  return (
    <div className={className}>
      <span className="sr-only">Subastas Insignia · Obras de Arte y Antigüedades</span>
      <BrandLockup className="h-[96px] sm:h-[120px] w-auto text-white mb-6" />
      <InsigniaMonogram className="h-[75px] sm:h-[84px] w-auto text-[#e2d7c0] opacity-90" />
    </div>
  );
}
